using Microsoft.EntityFrameworkCore;
using System.Text.Json.Nodes;
namespace Society.Api;
public record SelfProfileWrite(int Revision,string Profile,string? Privacy=null);
public static class IndividualSelfProfile {
 public static readonly string[] Fields=["photoUrl","preferredName","email","workEmail","phone","mobiles","addresses","city","state","country","pincode","dateOfBirth","anniversary","gender","languages","maritalStatus","spouseName","education","specialization","institution","graduationYear","employmentStatus","bloodGroup","emergencyContactName","emergencyContactPhone","otherInformation","professional"];
 static async Task<Membership> Own(Guid id,AppDb db,Access a)=>await MembershipExperience.Owned(db,a.UserId,true).SingleOrDefaultAsync(m=>m.Id==id&&db.MembershipCategories.Any(c=>c.Id==m.CategoryId&&c.Kind=="Individual")&&!EF.Functions.JsonContains(m.Profile,"{\"adminArchived\":true}"))??throw new AccessDeniedException();
 public static void Map(RouteGroupBuilder api){var t=api.MapGroup("/membership/my/{id:guid}/profile").RequireAuthorization();
 t.MapGet("/chapters",async(Guid id,AppDb db,Access a)=>{var m=await Own(id,db,a);return await db.Units.Where(u=>u.TenantId==m.TenantId&&u.Status=="Active"&&db.Levels.Any(l=>l.Id==u.LevelId&&l.Kind=="Chapter")).OrderBy(u=>u.Name).Select(u=>new{u.Id,u.Name,u.Code}).ToListAsync();});
 t.MapPost("/photo",async(Guid id,HttpRequest request,AppDb db,Access a,IObjectStore storage,MembershipService service)=>{if(request.ContentLength is null or >2097152)throw new DomainException("Choose a PNG photograph smaller than 2 MB");var m=await Own(id,db,a);using var data=new MemoryStream();await request.Body.CopyToAsync(data);var clean=AssetEndpoints.SanitizePng(data.ToArray());await using var tx=await db.Database.BeginTransactionAsync();await MembershipService.Lock(db,m.TenantId);await db.Entry(m).ReloadAsync();await Own(id,db,a);var asset=new Asset{TenantId=m.TenantId,Length=clean.Length};await storage.Put(m.TenantId,asset.Id,clean);db.Add(asset);var profile=MembershipService.Json(m.Profile);profile["selfPhotoAsset"]=asset.Id.ToString();profile["photoUrl"]=$"/api/v1/societies/{m.TenantId}/membership/members/{m.Id}/self-photo";m.Profile=profile.ToJsonString();m.Revision++;service.History(m,a.UserId,"membership.self.photo.updated",new{asset.Id});await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(new{url=profile["photoUrl"]!.ToString(),m.Revision});});
 api.MapGet("/societies/{tenant:guid}/membership/members/{id:guid}/self-photo",async(Guid tenant,Guid id,AppDb db,Access a,IObjectStore storage)=>{var m=await Own(id,db,a);if(m.TenantId!=tenant)throw new AccessDeniedException();var p=MembershipService.Json(m.Profile);if(!Guid.TryParse(p["selfPhotoAsset"]?.ToString(),out var asset)||!await db.Assets.AnyAsync(x=>x.Id==asset&&x.TenantId==tenant))return Results.NotFound();return Results.File(storage.Open(tenant,asset),"image/png");}).RequireAuthorization();
 t.MapGet("",async(Guid id,AppDb db,Access a)=>{var m=await Own(id,db,a);var p=await db.Persons.SingleAsync(p=>p.Id==m.PersonId);var source=MembershipService.Json(m.Profile);var visible=new JsonObject();foreach(var key in Fields)if(source[key]!=null)visible[key]=source[key]!.DeepClone();return Results.Ok(new{fullName=p.FullName,m.Number,m.Revision,profile=visible,privacy=MembershipService.Json(m.Privacy)});});
 t.MapPut("",async(Guid id,SelfProfileWrite r,AppDb db,Access a,MembershipService service)=>{await using var tx=await db.Database.BeginTransactionAsync();var m=await Own(id,db,a);await MembershipService.Lock(db,m.TenantId);await db.Entry(m).ReloadAsync();await Own(id,db,a);if(m.Revision!=r.Revision)return Results.Conflict(new{title="Profile changed. Refresh before saving."});var patch=MembershipService.Json(r.Profile);if(patch.Any(p=>!Fields.Contains(p.Key)))throw new DomainException("Only personal profile fields can be changed. Name and membership ID are fixed.");var before=m.Profile;var profile=MembershipService.Json(before);foreach(var pair in patch){if(pair.Value==null)profile.Remove(pair.Key);else profile[pair.Key]=pair.Value.DeepClone();}MembershipService.ValidateProfile(profile.ToJsonString());if(r.Privacy!=null){MembershipService.ValidatePrivacy(r.Privacy);m.Privacy=r.Privacy;}m.Profile=profile.ToJsonString();m.Revision++;service.History(m,a.UserId,"membership.self.profile.updated",new{before=MembershipService.Json(before),after=profile});await db.SaveChangesAsync();await tx.CommitAsync();return Results.NoContent();});
 t.MapDelete("",async(Guid id,[Microsoft.AspNetCore.Mvc.FromBody] RevisionRequest r,AppDb db,Access a,MembershipService service)=>{await using var tx=await db.Database.BeginTransactionAsync();var m=await Own(id,db,a);await MembershipService.Lock(db,m.TenantId);await db.Entry(m).ReloadAsync();await Own(id,db,a);if(m.Revision!=r.Revision)return Results.Conflict(new{title="Profile changed. Refresh before clearing."});var profile=MembershipService.Json(m.Profile);var before=profile.DeepClone();foreach(var key in Fields)profile.Remove(key);m.Profile=profile.ToJsonString();m.Revision++;service.History(m,a.UserId,"membership.self.profile.cleared",new{before,after=profile});await db.SaveChangesAsync();await tx.CommitAsync();return Results.NoContent();});
 }
 public record RevisionRequest(int Revision);
}
